    "appreciation": "《桃源行》是王維的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "漁舟逐水愛山春，兩岸桃花夾去津。",
        "pinyin": "yú zhōu zhú shuǐ ài shān chūn liǎng àn táo huā jiā qù jīn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "坐看紅樹不知遠，行盡青溪不見人。",
        "pinyin": "zuò kàn hóng shù bù zhī yuǎn xíng jǐn qīng xī bù jiàn rén",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "山口潛行始隈隩，山開曠望旋平陸。",
        "pinyin": "shān kǒu qián xíng shǐ wēi ào shān kāi kuàng wàng xuán píng lù",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "遙看一處攢雲樹，近入千家散花竹。",
        "pinyin": "yáo kàn yī chù zǎn yún shù jìn rù qiān jiā sàn huā zhú",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "樵客初傳漢姓名，居人未改秦衣服。",
        "pinyin": "qiáo kè chū chuán hàn xìng míng jū rén wèi gǎi qín yī fú",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "居人共住武陵源，還從物外起田園。",
        "pinyin": "jū rén gòng zhù wǔ líng yuán hái cóng wù wài qǐ tián yuán",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "月明松下房櫳靜，日出雲中雞犬喧。",
        "pinyin": "yuè míng sōng xià fáng lóng jìng rì chū yún zhōng jī quǎn xuān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "驚聞俗客爭來集，競引還家問都邑。",
        "pinyin": "jīng wén sú kè zhēng lái jí jìng yǐn hái jiā wèn dōu yì",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "平明閭巷埽花開，薄暮漁樵乘水入。",
        "pinyin": "píng míng lǘ xiàng sào huā kāi bó mù yú qiáo chéng shuǐ rù",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "初因避地去人間，及至成仙遂不還。",
        "pinyin": "chū yīn bì dì qù rén jiān jí zhì chéng xiān suì bù hái",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "峽裏誰知有人事，世中遙望空雲山。",
        "pinyin": "xiá lǐ shuí zhī yǒu rén shì shì zhōng yáo wàng kōng yún shān",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "不疑靈境難聞見，塵心未盡思鄉縣。",
        "pinyin": "bù yí líng jìng nán wén jiàn chén xīn wèi jǐn sī xiāng xiàn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "出洞無論隔山水，辭家終擬長游衍。",
        "pinyin": "chū dòng wú lùn gé shān shuǐ cí jiā zhōng nǐ zhǎng yóu yǎn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "自謂經過舊不迷，安知峰壑今來變。",
        "pinyin": "zì wèi jīng guò jiù bù mí ān zhī fēng hè jīn lái biàn",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "當時只記入山深，青溪幾曲到雲林。",
        "pinyin": "dāng shí zhǐ jì rù shān shēn qīng xī jǐ qū dào yún lín",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "春來遍是桃花水，不辨仙源何處尋。",
        "pinyin": "chūn lái biàn shì táo huā shuǐ bù biàn xiān yuán hé chù xún",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
