    "appreciation": "《謁衡嶽廟遂宿嶽寺題門樓》是韓愈的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "五嶽祭秩皆三公，四方環鎮嵩當中。",
        "pinyin": "wǔ yuè jì zhì jiē sān gōng sì fāng huán zhèn sōng dāng zhōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "火維地荒足妖怪，天假神柄專其雄。",
        "pinyin": "huǒ wéi dì huāng zú yāo guài tiān jiǎ shén bǐng zhuān qí xióng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "噴雲泄霧藏半腹，雖有絕頂誰能窮。",
        "pinyin": "pēn yún xiè wù cáng bàn fù suī yǒu jué dǐng shuí néng qióng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "我來正逢秋雨節，陰氣晦昧無清風。",
        "pinyin": "wǒ lái zhèng féng qiū yǔ jié yīn qì huì mèi wú qīng fēng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "潛心默禱若有應，豈非正直能感通。",
        "pinyin": "qián xīn mò dǎo ruò yǒu yīng qǐ fēi zhèng zhí néng gǎn tōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "須臾靜掃衆峰出，仰見突兀撐青空。",
        "pinyin": "xū yú jìng sǎo zhòng fēng chū yǎng jiàn tū wù chēng qīng kōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "紫蓋連延接天柱，石廩騰擲堆祝融。",
        "pinyin": "zǐ gài lián yán jiē tiān zhù shí lǐn téng zhì duī zhù róng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "森然魄動下馬拜，松柏一逕趨靈宮。",
        "pinyin": "sēn rán pò dòng xià mǎ bài sōng bǎi yī jìng qū líng gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "粉牆丹柱動光彩，鬼物圖畫填青紅。",
        "pinyin": "fěn qiáng dān zhù dòng guāng cǎi guǐ wù tú huà tián qīng hóng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "升階傴僂薦脯酒，欲以菲薄明其衷。",
        "pinyin": "shēng jiē yǔ lóu jiàn pú jiǔ yù yǐ fěi bó míng qí zhōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "廟令老人識神意，睢盱偵伺能鞠躬。",
        "pinyin": "miào lìng lǎo rén shí shén yì suī xū zhēn cì néng jū gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "手持桮珓導我擲，云此最吉餘難同。",
        "pinyin": "shǒu chí bēi jiào dǎo wǒ zhì yún cǐ zuì jí yú nán tóng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "竄逐蠻荒幸不死，衣食纔足甘長終。",
        "pinyin": "cuàn zhú mán huāng xìng bù sǐ yī shí cái zú gān zhǎng zhōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "侯王將相望久絕，神縱欲福難爲功。",
        "pinyin": "hóu wáng jiāng xiāng wàng jiǔ jué shén zòng yù fú nán wèi gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "夜投佛寺上高閣，星月掩暎雲朣朧。",
        "pinyin": "yè tóu fó sì shàng gāo gé xīng yuè yǎn yìng yún tóng lóng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "猿鳴鐘動不知曙，杲杲寒日生於東。",
        "pinyin": "yuán míng zhōng dòng bù zhī shǔ gǎo gǎo hán rì shēng yú dōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
