    "appreciation": "《古柏行》是杜甫的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "孔明廟前有老柏，柯如青銅根如石。",
        "pinyin": "kǒng míng miào qián yǒu lǎo bǎi kē rú qīng tóng gēn rú shí",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "霜皮溜雨四十圍，黛色參天二千尺。",
        "pinyin": "shuāng pí liū yǔ sì shí wéi dài sè cān tiān èr qiān chǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "君臣已與時際會，樹木猶爲人愛惜。",
        "pinyin": "jūn chén yǐ yǔ shí jì huì shù mù yóu wèi rén ài xī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "雲來氣接巫峽長，月出寒通雪山白。",
        "pinyin": "yún lái qì jiē wū xiá zhǎng yuè chū hán tōng xuě shān bái",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "憶昨路繞錦亭東，先主武侯同閟宮。",
        "pinyin": "yì zuó lù rào jǐn tíng dōng xiān zhǔ wǔ hóu tóng bì gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "崔嵬枝幹郊原古，窈窕丹青戶牖空。",
        "pinyin": "cuī wéi zhī gàn jiāo yuán gǔ yǎo tiǎo dān qīng hù yǒu kōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "落落盤踞雖得地，冥冥孤高多烈風。",
        "pinyin": "luò luò pán jù suī dé dì míng míng gū gāo duō liè fēng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "扶持自是神明力，正直原因造化功。",
        "pinyin": "fú chí zì shì shén míng lì zhèng zhí yuán yīn zào huà gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "大廈如傾要梁棟，萬牛回首丘山重。",
        "pinyin": "dà shà rú qīng yào liáng dòng wàn niú huí shǒu qiū shān zhòng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "不露文章世已驚，未辭剪伐誰能送。",
        "pinyin": "bù lù wén zhāng shì yǐ jīng wèi cí jiǎn fá shuí néng sòng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "苦心豈免容螻蟻，香葉終經宿鸞鳳。",
        "pinyin": "kǔ xīn qǐ miǎn róng lóu yǐ xiāng yè zhōng jīng sù luán fèng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "志士幽人莫怨嗟，古來材大難爲用。",
        "pinyin": "zhì shì yōu rén mò yuàn jiē gǔ lái cái dà nán wèi yòng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
    "image": "https://readforfun-img.chunyangwen.com/tang-shi/images/du-fu---gu-bai-xing/poem.svg"
