    "appreciation": "《與高適薛據慈恩寺浮圖》是岑參的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "塔勢如湧出，孤高聳天宮。",
        "pinyin": "tǎ shì rú yǒng chū gū gāo sǒng tiān gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "登臨出世界，磴道盤虛空。",
        "pinyin": "dēng lín chū shì jiè dèng dào pán xū kōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "突兀壓神州，崢嶸如鬼工。",
        "pinyin": "tū wù yā shén zhōu zhēng róng rú guǐ gōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "四角礙白日，七層摩蒼穹。",
        "pinyin": "sì jiǎo ài bái rì qī céng mó cāng qióng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "下窺指高鳥，俯聽聞驚風。",
        "pinyin": "xià kuī zhǐ gāo niǎo fǔ tīng wén jīng fēng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "連山若波濤，奔湊似朝東。",
        "pinyin": "lián shān ruò bō tāo bēn còu shì cháo dōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "青槐夾馳道，宮館何玲瓏。",
        "pinyin": "qīng huái jiā chí dào gōng guǎn hé líng lóng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "秋色從西來，蒼然滿關中。",
        "pinyin": "qiū sè cóng xī lái cāng rán mǎn guān zhōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "五陵北原上，萬古青濛濛。",
        "pinyin": "wǔ líng běi yuán shàng wàn gǔ qīng méng méng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "淨理了可悟，勝因夙所宗。",
        "pinyin": "jìng lǐ le kě wù shèng yīn sù suǒ zōng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "誓將挂冠去，覺道資無窮。",
        "pinyin": "shì jiāng guà guān qù jué dào zī wú qióng",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
