    "appreciation": "《尋西山隱者不遇》是丘爲的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "絕頂一茅茨，直[上]三十里。",
        "pinyin": "jué dǐng yī máo cí zhí shàng sān shí lǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "扣關無僮僕，窺室唯案几。",
        "pinyin": "kòu guān wú tóng pú kuī shì wéi àn jǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "若非巾柴車，應是釣秋水。",
        "pinyin": "ruò fēi jīn chái chē yīng shì diào qiū shuǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "差池不相見，黽勉空仰止。",
        "pinyin": "chā chí bù xiāng jiàn miǎn miǎn kōng yǎng zhǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "草色新雨中，松聲晚牕裏。",
        "pinyin": "cǎo sè xīn yǔ zhōng sōng shēng wǎn chuāng lǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "及茲契幽絕，自足蕩心耳。",
        "pinyin": "jí zī qì yōu jué zì zú dàng xīn ěr",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "雖無賓主意，頗得清淨理。",
        "pinyin": "suī wú bīn zhǔ yì pō dé qīng jìng lǐ",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "興盡方下山，何必待之子。",
        "pinyin": "xìng jǐn fāng xià shān hé bì dài zhī zi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
