    "appreciation": "《夢李白二首 一》是杜甫的名篇。全诗从具体景物和真切情感出发，语言凝练，意境悠远，适合结合课本诵读与赏析。",
    "lines": [
      {
        "text": "死別已吞聲，生別常惻惻。",
        "pinyin": "sǐ bié yǐ tūn shēng shēng bié cháng cè cè",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "江南瘴癘地，逐客無消息。",
        "pinyin": "jiāng nán zhàng lì dì zhú kè wú xiāo xī",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "故人入我夢，明我長相憶。",
        "pinyin": "gù rén rù wǒ mèng míng wǒ zhǎng xiāng yì",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "恐非平生魂，路遠不可測。",
        "pinyin": "kǒng fēi píng shēng hún lù yuǎn bù kě cè",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "魂來楓葉青，魂返關塞黑。",
        "pinyin": "hún lái fēng yè qīng hún fǎn guān sāi hēi",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "君今在羅網，何以有羽翼。",
        "pinyin": "jūn jīn zài luó wǎng hé yǐ yǒu yǔ yì",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "落月滿屋梁，猶疑照顏色。",
        "pinyin": "luò yuè mǎn wū liáng yóu yí zhào yán sè",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      },
      {
        "text": "水深波浪闊，無使蛟龍得。",
        "pinyin": "shuǐ shēn bō làng kuò wú shǐ jiāo lóng dé",
        "translation": "结合语境理解诗句，感受诗人写景、抒情与言志的表达。",
        "explanation": "重点体会字词、意象和情感。"
      }
    ],
